//! Property 3: every write function is safe to replay with identical input -- row counts
//! must not change on a second call. This is the property the whole ingestion design leans
//! on (a restarted worker or an at-least-once stream re-delivers the same event) and the
//! one most likely to break silently, since a missing `ON CONFLICT` clause still compiles
//! and still "works" the first time.
//!
//! Not every write function in `storage` gets a test here: `insert_signal` and
//! `open_paper_position` key on a fresh `Uuid` generated by the caller, not a natural key,
//! so replaying the *same* row is not a scenario production code ever produces -- doing so
//! deliberately hits the primary key and returns an error, which is correct, not a defect.
//! `rationale`/`position_marks`/`outcomes`, which key on a natural (parent_id, ordinal)
//! pair, are covered below instead.

use chrono::{DateTime, Utc};
use rust_decimal::Decimal;
use std::str::FromStr;
use storage::types::{Timeframe, quality, venue};
use storage::write::{
    IndicatorRow, NewActiveBinSnapshot, NewBinState, NewDlmmPoolState, NewFeeParamUpdate,
    NewLiquidityEvent, NewOutcome, NewPaperPosition, NewPoolMetrics10mBucket, NewPoolMetricsBucket,
    NewPoolSnapshot, NewPositionMark, NewRationaleItem, NewRegimeStateRow, NewSignal, NewSwap,
    NewToken, NewVolatilityStateRow, insert_active_bin_snapshots, insert_bin_states,
    insert_fee_param_updates, insert_liquidity_events, insert_pool_state, insert_position_marks,
    insert_rationale, insert_signal_with_rationale, insert_swaps, mute_pool, open_paper_position,
    upsert_indicators, upsert_outcome, upsert_pool_metrics_5m, upsert_pool_metrics_10m,
    upsert_regime_state, upsert_token, upsert_volatility_state,
};

fn t() -> DateTime<Utc> {
    integration::fixture_time()
}

fn dec(s: &str) -> Decimal {
    Decimal::from_str(s).unwrap()
}

async fn row_count(pool: &sqlx::PgPool, table: &str, pool_address: &str) -> i64 {
    sqlx::query_scalar::<_, i64>(&format!(
        "SELECT count(*) FROM {table} WHERE pool_address = $1"
    ))
    .bind(pool_address)
    .fetch_one(pool)
    .await
    .unwrap_or_else(|e| panic!("counting rows in {table}: {e}"))
}

