#[tokio::test]
async fn test_rationale_replay_is_idempotent() {
    let pool = integration::require_database!();
    let pool_address = "idempotent_rationale";
    integration::ensure_pool(&pool, pool_address).await;
    integration::reset_pool_fixture(&pool, pool_address).await;

    let signal_id = uuid::Uuid::new_v4();
    let signal = NewSignal {
        id: signal_id,
        ts: t(),
        pool_address: pool_address.to_string(),
        venue: venue::DLMM,
        timeframe: "5m".to_string(),
        kind: "POTENTIAL".to_string(),
        regime: Some("V1".to_string()),
        numbers: None,
        config_hash: "hash_idempotent_rationale".to_string(),
        expires_at: None,
    };
    let items = vec![NewRationaleItem {
        signal_id,
        seq: 0,
        venue: venue::DLMM,
        signal: "r_org".to_string(),
        observed: Some("2.5".to_string()),
        cmp: Some(">=".to_string()),
        threshold: Some("2.0".to_string()),
        passed: true,
        note: None,
    }];

    insert_signal_with_rationale(&pool, &signal, &items)
        .await
        .unwrap();

    // The signal itself has no natural key (a fresh row every real call, by design) --
    // only replaying the rationale rows for an already-existing signal is a realistic
    // scenario, e.g. a worker retrying the second half of a partially-failed write.
    insert_rationale(&pool, &items).await.unwrap();

    let count: i64 = sqlx::query_scalar("SELECT count(*) FROM rationale WHERE signal_id = $1")
        .bind(signal_id)
        .fetch_one(&pool)
        .await
        .unwrap();
    assert_eq!(count, 1);
}

